/* ====== 全局字体====== */


@import url("https://fontsapi.zeoseven.com/256/main/result.css");

body {
    font-family: "Huiwen-mincho";
    font-weight: normal;
}
/*———————— 顶栏 ————————*/
#top-bar {
    position: fixed !important;  
    overflow: visible !important;
    background: none !important;
    border: 0 !important;
    box-shadow: none !important;
    pointer-events: none;
    width: 100vw;  /*宽度*/
    height: 100px;  
    top: 0;
    left: 0;
}

#top-bar::before {
    content: "";
    position: fixed;
    background:  url("https://iili.io/BOhvD6G.png") no-repeat center / cover;  

    /*⭕️顶栏核心 */
    top: 0px;
    left: 0px;
    right: 0px;
    bottom: 30px;/*⭕️只有这里需要改*/


    z-index: 5;
    pointer-events: auto;

    transform: none !important;
    animation: none !important;
}


/* ⭕️顶栏装饰层 */
#top-bar::after {
      pointer-events: none; /* 点击会穿透到下层元素 */
    content: "";
    position: fixed;
    background: url("") no-repeat center / contain;
    width: 260px;
    height: 200px;
    top: -65px;
    right: 80px;
    z-index: 6;

    transform-origin: top center;
}






/* —————面板背景———— */
.drawer-content {
 background-image: url('https://iili.io/BOPcEj2.png'); /* 面板背景 */
  background-size: cover; 
  background-position: center; 
  background-repeat: no-repeat; 
  background-attachment: fixed; 

}



/* ===== ⭕️楼层箭头、计数器核心 ===== */

.fa-chevron-right:before,
.fa-chevron-left:before,
.fa-arrow-right:before {
  content: "" !important;
  display: none !important; 
}
.fa-chevron-left,
.fa-chevron-right {
  display: inline-block;
  width: 20px;
  height: 20px; 
  min-width: 0;
  opacity: 1 !important; 
  background: center/contain no-repeat;
opacity: 1 !important;

}

.fa-chevron-left {
  background-image: url('https://iili.io/BOh8JuS.png'); /* 左 */
  margin-bottom: -39px; 

padding: 0px 330px 0;
}
.fa-chevron-right {
  background-image: url('https://iili.io/BOh8JuS.png'); /* 右 */
  top: 50% !important;
  left: 0% !important;
  transform: translate(-70%, 93%) !important;
  z-index: 9999 !important;
}
/* ===== 楼层计数器样式 ===== */
.swipes-counter {
  font-size: 9px;
  font-weight: 540;
  opacity: 0.9 !important;
  color: #000 !important;
}
.swipes-counter {
  position: absolute;
  top: 22px;
  right: 96px;
  z-index: 9999;
  pointer-events: none;
}

/* ==============================================
🦋气泡拼接开始🦋 *==============================================*/



/* 🍃 中层气泡*/
.mes {
   z-index: -3;
  max-width: 425px;/*【🍃宽度】*/
  width: 100%;/*【👁宽度，一般调整第一个就行，没效果再调整这个】*/
  margin: 250px auto 100px;/*【AI和用户的气泡距离⭕️第一个是调整最早的消息与顶部的距离防止顶部超过屏幕】*/
  border-radius: 0px;
  background: url('https://iili.io/BOhkTJV.png') repeat-y !important;
background-size: 100% auto !important;
  background-size: 100% auto; 
  background-attachment: local; 
  transition: transform 0.2s ease; 
  transform-origin: top center;
  position: relative;
  overflow: visible;
  box-shadow: none !important; 
}

/* 🍃上层装饰层、拼接气泡顶部 */
.mes::before {
  content: "";
  position: absolute;
  top: -231.5px; /* 【上下】(负值向上) */
  left: 0%; /* 左右 */
  width: 423px; /* 【宽度/大小】 */
  height: 400px; /* 【高度/大小】 */
  background-image: url('https://iili.io/BOhvf7p.png'); 
  background-size: contain; 
  background-repeat: no-repeat; 
  z-index: -2; 
  pointer-events: none; 
}

/* 🍃下层装饰层、拼接气泡尾部 */
.mes::after {
  content: "";
  position: absolute;
  bottom: -202px; /* 【上下】(负值向下) */
  left: 0%; /* 左右 */
  width: 423px; /* 【宽度/大小】 */
  height: 252px; /* 【高度/大小👁会影响最新消息的底部留白，不可调太高，宽度拉不动再调高一点】 */
background-image: url("https://iili.io/BOhkD7V.png"); 
  background-size: contain; 
  background-repeat: no-repeat;
  z-index: -4; 
  pointer-events: none; 
}
/*——————🍃文本边距——————*/

 .mes_text,
.mes_reasoning {
    font-weight: 300; 
    line-height: 1.9; /* 行高 */
    text-align: justify; 
    text-justify: inter-word; 
    overflow-wrap: anywhere;
    hyphens: auto; 

    /* 优化后的间距系统 */
    --top-padding: 9rem;    /* 顶部 */
    --bottom-padding: 2rem; /* 底部 */
    --left-padding: 0.1rem;  /* 左侧 */
    --right-padding: 0.8rem; /* 右侧 */


    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);

    max-width: 100ch;

    margin: 0 auto; 

    /* 高级排版增强 */
    font-kerning: normal; 
    letter-spacing: 0.01em; 
    text-rendering: optimizeLegibility; 
}

.mes_reasoning::first-letter {
    font-weight: 600;
    margin-right: 0.5em;
}
/*@咩野老师lambkinling*/
.mes_text {
  /* 文字两端对齐justify，左对齐改成left，居中改成center  */
  text-align: justify;
}



/* ==============================================
🦋气泡拼接结束🍃头像美化开始============================================== */


/*⭕️头像框*/
.mesAvatarWrapper {
  position: absolute;
  top: -147px;
  left: 48.9%;
  transform: translateX(-50%);
  z-index: -1;
  width: 70px;  
  height: 70px; 
  overflow: visible; 
}

/* ⭕️头像框位置与大小调整核心 */
.mesAvatarWrapper::after {
  content: "";
  position: absolute;
  top: 123%;/* 【上下】 */
  left: 102%;/* 【左右】 */
  width: 320%;  /* 【框宽度】 */
  height: 372%; /* 【框高度】 */
  display: block;

  /* ⭕️头像框链接放置处 */
  background-image: url('https://iili.io/BOhv0Qe.png');/*←🍃*/
  background-size: 100% 100%;
  background-repeat: no-repeat;
  background-position: center;
  transform: translate(-50%, -50%);
  z-index: 1; 

}

.mesAvatarWrapper img {
  position: relative;
  z-index: -1; 
}

/* ⭕️头像位置 */
.mesAvatarWrapper {
  position: absolute;
  top: -182px;           /* 【负值向上】 */
  left: 41.9%; /* 左右 */
    transform: translateX(-50%); 
  z-index: -1;
    filter: 
    saturate(0.7) !important;/* 【头像饱和度,默认改1】 */
}

/* ⭕️头像尺寸*/
.mesAvatarWrapper .avatar {
  /* 🍃头像尺寸 */
  width: 145px;           /* 宽度 */
  height: 158px;          /* 高度 */
  transform: rotate(0deg); /* 旋转 */
}
.mesAvatarWrapper .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ⭕user设置页面/角色选择头像美化⭕*/
/*收藏头像黄圈隐藏、名字颜色修改@Little YE*/
.character_select.is_fav .avatar {
  outline: none !important;
}
.character_select.is_fav .ch_name {
  color: #797264 !important;
}
.avatar img {
    border: 2px solid white; /* 头像描边 */
box-shadow:2px 2px 1px rgba(0, 0, 0, 0.3);
}
/* user */
.avatar-container {
    position: relative; 
    border-radius: 0px;
    background: url('https://iili.io/BO8PZZX.png') repeat-y !important;
background-size: 100% auto !important;
    color: #000;
    box-shadow:
0 0 0 1.2px #424240,
0 0 0 2.5px #fcfef8,
0px 0px 4px rgba(0, 0, 0, 1);
