    saturate(1) !important;/* 【头像饱和度,默认改1】 */
margin-top: 10px;
}


/* char */
.bogus_folder_select,
.character_select {
    position: relative;
border-radius: 0px;
    background: url('https://iili.io/BO8PZZX.png') repeat-y !important;
background-size: 100% auto !important;
