    color: #898376;
}

/* 代码块 */
code, pre {
background: #f8f7f5 !important;
border-radius: 10px 10px 0px 0px;
border: 0px solid #fff; /* 白色描边 */
  box-shadow:
0 0 0 1px #424240,
0 0 0 2.5px #fcfef8,
2px 2px 2px rgba(0, 0, 0, 0.9);
    color: #000;

font-weight: 500;
line-height: 1.5; 
padding: 0px 5px;

    font-family: "Huiwen-mincho";
    font-weight: normal;
}


code, pre {
  position: relative;
  overflow: visible !important;
}
/* 引用气泡 */
.mes_text q {
    background:  #fff ;
  padding-bottom: 0px;

  -webkit-box-decoration-break: clone;
border: 2px solid #ffffff !important;
box-shadow: 
    0px 1px 0px rgba(0,0,0, 0.2) !important;
  border-radius: 0px 0px 0px 0px !important;
font-weight: 500;
line-height: 1.5;
padding: 0px 2px;
}


/* 引用区块 */
.mes_text blockquote, 
.mes_reasoning blockquote {
  border-left:2px solid #520c0c !important;
  background: linear-gradient(to right, rgba(255, 255, 255, 0.0) 0%, transparent 100%) !important;
  color: #0c1e53 !important; 
  box-shadow: 
    inset 2px -0px 2px rgba(0, 0, 0,0),
    -3px -3px 4px rgba(245, 189, 206, 0);
