}
.mes_text blockquote,
.mes_reasoning blockquote {
    padding-left: 8px;
    padding-right: 10px;
}
/* ——自定义文本选中样式@时鸢 —— */
::selection {
    background-color: rgba(70, 80, 108, 0.9); 
    color: #fff;                 
    text-shadow: none;   
}

/* Firefox 兼容 */
::-moz-selection {
    background-color: rgba(70, 80, 108, 0.9); 
    color: #fff;
    text-shadow: none;
}

/* 输入框内的选中样式（可选） */
input::selection,
textarea::selection {
    background-color: rgba(70, 80, 108, 0.9); 
    color: #fff;
}
/* ==============================================
🦋文字效果美化结束🍃零碎美化开始============================================== */

/*—— 🍃楼层 ——*/


.mes .mesIDDisplay {
    position: fixed;
    top: 134.5px;
    left: -119px;                    /* 从左侧开始定位 */
  transform: none;            /* 移除所有变换效果 */
    z-index: 2;
    text-align: left;           /* 文字左对齐 */
    width: auto;                /* 宽度自适应内容 */
    white-space: nowrap;        /* 防止文字换行 */
    padding: 0 10px;            /* 添加左右内边距 */
    gap: 2px;            /* 【左右文字间距】 */

    opacity: 1;
    font-size: calc(var(--mainFontSize) * 0.7);
    font-weight: 300;
    color: #5c6275;      /* 【颜料🎨】【主文字颜色】 */
transform: rotate(-6deg); /* 旋转 */
}
/* 左侧文字 */
.mes .mesIDDisplay::before {
    content: var(--left-text, ""); /* 【左侧文字内容】 */
    white-space: nowrap;  
    color: var(--left-color, #000); /* 【颜料🎨】【左侧文字颜色】 */
    font-weight: 300;
}

/* 右侧文字 */
.mes .mesIDDisplay::after {
    content: var(--right-text, ""); /* 【右侧文字内容】 */
    white-space: nowrap;  
    color: var(--right-color, #000); /* 【颜料🎨】【右侧文字颜色】 */
    font-weight: 300;
}

/*—— 🍃基础信息【时间戳、角色昵称等】 ——*/

/* ⭕️消息文字上边距留白核心调整 */
.mes_block {
  position: relative;
  margin-top: -120px;  
  overflow: visible;
}

/* ⭕️角色名称核心调整 */
.mes_block .ch_name {
  position: relative;
