  z-index: 10; 
  font-size: 0.9em;
  font-weight: 300;
  transform: rotate(-0deg); /* 旋转 */
  color: #5c6275 !important; 

}





/* ⭕️编辑按钮核心调整 */
.mes_buttons {
  position: relative;
  top: -40px; /*上下*/
  left:63px;/*左右*/
