}
.mes_button, .extraMesButtons>div {

    filter: none !important;
    /* ⭕设置省略号菜单颜色 */
    color: #4b4e58 !important;
opacity: 1 !important; 
  ;
}

/*—— 计时器&字符——*/
.mes {
  position: relative; 
}

.mes .mes_timer,
.mes .tokenCounterDisplay {
  position: fixed; 
  z-index: 3; 
  cursor: default;
opacity: 1;/*透明度*/
  white-space: nowrap; 
  font-size: calc(var(--mainFontSize) * 0.7);/*文字大小*/
  font-weight: 300;/*文字粗细*/
  padding: 0;
  top: var(--element-top, 240px);
  left: var(--element-left, 50%);
  transform: translateX(var(--element-translate, -50%));
transform: rotate(0deg); /* 旋转 */
}


/* === ⭕️计时器核心 === */
.mes .mes_timer {
  --element-top: var(--counter-top, 181px); /* 【🍃計時器计数器上下】 */
  --element-left: var(--counter-left, 310%); /* 【🍃计时器计数器左右】 */
  --element-translate: var(--counter-translate, -0%); 

  --counter-prefix: ""; /* 【🍃前缀】 */
  --counter-suffix: ""; /* 【🍃后缀】 */

  --counter-main-color: #4b4e58; /* 【🍃计时器颜色】 */
}

/* === 字符计数器单独设置 === */
.mes .tokenCounterDisplay {
  text-align: left;
  --element-top: var(--counter-top, 76px); /* 【🍃字符计数器上下】 */
  --element-left: var(--counter-left, 290%); /* 【🍃字符计数器左右】 */
  --element-translate: var(--counter-translate, -0%); 

  --counter-prefix: ""; /* 【🍃前缀】 */
  --counter-suffix: ""; /* 【🍃后缀】 */
transform: rotate(14deg); /* 旋转 */
  --counter-main-color: #4b4e58; /* 【🍃计数器颜色】 */

}
