/*加载更多消息*/
#show_more_messages {
    text-align: center;
    margin: 99px auto;
    font-weight: 500;
    order: -1;
    cursor: pointer;
    padding: 0.5em 1em;
    background:url('https://iili.io/BElRUS1.png') center/cover, #ededed !important;
    width: fit-content;
    border-radius: 0px;
    box-shadow:
0 0 0 1.2px #424240,
0 0 0 2.5px #fcfef8,
0px 0px 4px rgba(0, 0, 0, 1);
    color: transparent;
    position: relative;
    display: block; 
    z-index: 10; 
    min-height: 20px; 
}

#show_more_messages::after {
    content: "树是梧桐树，城是南京城";
    color: #000;
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: none; 
}
